.libPaths(c('work/stage5_Rlib',.libPaths()));library(susieR);library(coloc)
base<-read.csv('outputs/stage6_foxp2_gnomad_narrow_variants.csv');d<-read.csv('outputs/stage6_portas_nrem_foxp2_aligned.csv');sel<-match(d$rs,base$rs);stopifnot(!anyNA(sel),!anyDuplicated(sel));p0<-nrow(base);p<-nrow(d)
readR<-function(pop){M<-matrix(readBin(paste0('work/stage6_foxp2_gnomad_',pop,'_narrow_ld.bin'),'double',n=p0*p0,size=8,endian='little'),p0,p0);M<-M[sel,sel];dimnames(M)<-list(d$rs,d$rs);stopifnot(min(eigen(M,symmetric=TRUE,only.values=TRUE)$values)> -1e-8);M};Rn<-readR('nfe');Rf<-readR('fin')
traits<-c('NREM','MVP_insomnia','FinnGen_HFRS');ns<-c(80013,253769,500737);zs<-list(d$nrem_z_anchor,d$mvp_z_anchor,d$hfrs_z_anchor);fits<-list();diag<-list();members<-list()
for(i in seq_along(traits)){R<-if(traits[i]=='FinnGen_HFRS')Rf else Rn;z<-zs[[i]];names(z)<-d$rs;lambda<-estimate_s_rss(z,R,n=ns[i]);set.seed(42);f<-susie_rss(z=z,R=R,n=ns[i],L=10,coverage=.95,estimate_residual_variance=FALSE,max_iter=500);fits[[traits[i]]]<-f;diag[[i]]<-data.frame(trait=traits[i],n=ns[i],n_variants=p,lambda=lambda,converged=f$converged,iterations=f$niter,n_sets=length(f$sets$cs),max_pip=max(f$pip));if(length(f$sets$cs))for(k in seq_along(f$sets$cs)){ii<-f$sets$cs[[k]];members[[length(members)+1]]<-data.frame(trait=traits[i],component=f$sets$cs_index[k],rs=d$rs[ii],pip=f$pip[ii])};cat(traits[i],'sets',length(f$sets$cs),'lambda',lambda,'converged',f$converged,'\n');flush.console()}
write.csv(do.call(rbind,diag),'outputs/stage6_portas_nrem_foxp2_susie_diagnostics.csv',row.names=FALSE);if(length(members))write.csv(do.call(rbind,members),'outputs/stage6_portas_nrem_foxp2_susie_members.csv',row.names=FALSE);saveRDS(fits,'work/stage6_portas_nrem_foxp2_susie_fits.rds');out<-list()
for(pair in list(c('NREM','MVP_insomnia'),c('NREM','FinnGen_HFRS'),c('MVP_insomnia','FinnGen_HFRS'))){a<-fits[[pair[1]]];b<-fits[[pair[2]]];if(!length(a$sets$cs)||!length(b$sets$cs))next;for(p12 in c(1e-6,1e-5,5e-5)){x<-as.data.frame(coloc.susie(a,b,p1=1e-4,p2=1e-4,p12=p12)$summary);x$trait1<-pair[1];x$trait2<-pair[2];x$p12<-p12;out[[length(out)+1]]<-x}}
if(length(out))write.csv(do.call(rbind,out),'outputs/stage6_portas_nrem_foxp2_coloc.csv',row.names=FALSE)
